package ledger

import "fmt"

type memLedger struct {
	balances map[string]int64
	history  map[string][]Entry
	known    map[string]bool
}

// NewLedger creates a new Ledger with the given starting balances.
func NewLedger(starting map[string]int64) Ledger {
	l := &memLedger{
		balances: make(map[string]int64),
		history:  make(map[string][]Entry),
		known:    make(map[string]bool),
	}
	for acct, bal := range starting {
		l.balances[acct] = bal
		l.known[acct] = true
	}
	return l
}

func (l *memLedger) Record(e Entry) error {
	if e.Amount == 0 {
		return ErrZeroAmount
	}
	cur := l.balances[e.Account]
	newBal := cur + e.Amount
	if newBal < 0 {
		return fmt.Errorf("record entry for account %q: %w", e.Account, ErrInsufficient)
	}
	l.balances[e.Account] = newBal
	l.known[e.Account] = true
	l.history[e.Account] = append(l.history[e.Account], e)
	return nil
}

func (l *memLedger) Balance(account string) (int64, error) {
	if !l.known[account] {
		return 0, fmt.Errorf("balance for account %q: %w", account, ErrUnknownAccount)
	}
	return l.balances[account], nil
}

func (l *memLedger) History(account string) ([]Entry, error) {
	if !l.known[account] {
		return nil, fmt.Errorf("history for account %q: %w", account, ErrUnknownAccount)
	}
	src := l.history[account]
	out := make([]Entry, len(src))
	copy(out, src)
	return out, nil
}

